com.mirth.connect.plugins.javascriptstep.script:
//Get DB information
var jdbdcDriver = configurationMap.get("jdbdcDriver");
var jbdcUrl = configurationMap.get("jbdcUrl");
var dbName = configurationMap.get("dbName");
var dbPassword = configurationMap.get("dbPassword");
var username = configurationMap.get("screeningdlUserName");
var password = configurationMap.get("screeningdlPassword");
var ip = configurationMap.get("screeningdlHost");
var port = configurationMap.get("screeningdlPort");
var privateKey = configurationMap.get("screeningdlPrivatekey");
var validData = [];
var msgObj = [];
var errors = {};
// var fileNames = [];
var validationStatus = true;
var controlFileValid = true;
var errorsToAppend = [];
var fileInformation = [];
var filePart = JSON.parse(configurationMap.get("filePart"));
var filePartJSON = {};
if (filePart.length > 0) {
  filePart.forEach((file) => {
    filePartJSON[file] = 0;
  });
}
var content = connectorMessage.getRawData();
var dbConn;
var scrPerferenceMap = globalChannelMap.get("scrPerferenceMap");
logger.info("message" + content);

//Since config map store it as string, parse it into json
var errorCodeString = configurationMap.get("screeningErrorCodes");
var errorCodes = JSON.parse(errorCodeString);
var screeningPath = configurationMap.get("screeningLocation");
var screeningLocation = JSON.parse(screeningPath);
//logger.info(screeningLocation);
var resourceTypeId = globalChannelMap.get("flatFileResourceId");
//logger.info("resourceTypeId" + resourceTypeId);
var errorTypeMap = globalChannelMap.get("errorTypeMap");
//logger.info("erroMap" + errorTypeMap);
var controlFileHeader = String(configurationMap.get("controlFileHeader"));
//logger.info("header" + controlFileHeader);
var mcoMap = globalChannelMap.get("mcoMap");
var sdf = new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'");
sdf.setTimeZone(java.util.TimeZone.getTimeZone("UTC")); // ensure UTC
var utcTimeString = new java.util.Date();
var now = sdf.format(utcTimeString);
var originalFileName = sourceMap.get("originalFilename");
var originalFileSize = sourceMap.get("fileSize");
var controlFileContent = [];
var isInvalidFile = false;
var generalInbound = screeningLocation["NYEC"]["inbound"];
var generalProcessed = screeningLocation["NYEC"]["nyecProcessed"];
var generalTemp = screeningLocation["NYEC"]["temp"];
var dbConn;
var sftp = null;
var File = Packages.java.io.File;
var FileInputStream = Packages.java.io.FileInputStream;
var FileOutputStream = Packages.java.io.FileOutputStream;
var BufferedReader = Packages.java.io.BufferedReader;
var InputStreamReader = Packages.java.io.InputStreamReader;
var isPreferred;
var fileNameScreeningDetailIdMap = {};
try {
  //Get the chunk size - used for getting correct row numbers
  //Original file name as read from the SFTP
  var filename = originalFileName;
  //logger.info("fileName" + filename);
  // fileNames.push(filename);
  var splittedFileName = filename.split("_");
  if (
    filename &&
    splittedFileName.length > 0 &&
    splittedFileName[0] &&
    scrPerferenceMap[splittedFileName[0].toUpperCase()]
  ) {
    isPreferred = true;
  } else {
    isPreferred = false;
  }
  channelMap.put("preference", isPreferred);

  if (!splittedFileName || splittedFileName.length !== 3) {
    isInvalidFile = true;
    controlFileValid = false;
    if (splittedFileName) {
      var mco_code = splittedFileName[0].toUpperCase();
      channelMap.put("mcoCode", mco_code);
    }
  } else {
    var mco_code = splittedFileName[0].toUpperCase();
    //logger.info("logger1" + splittedFileName[0]);
    var secondPart = splittedFileName[1];
    var thirdPart = splittedFileName[2]; // Expected format: YYYYMMDD.txt

    channelMap.put("mcoCode", mco_code);

    // Check if MCO code maps to a screening path
    var path = screeningLocation[mco_code];
    //logger.info(path);
    if (!path) {
      //logger.info("logging inside 75" + path);
      isInvalidFile = true;
      controlFileValid = false;
      //logger.info("controlFileValid 75" + controlFileValid);
    }

    // Check second part is 'control'
    if (secondPart.toString().toLowerCase() != "control") {
      //logger.info(secondPart.toString().toLowerCase());
      isInvalidFile = true;
      controlFileValid = false;
      //logger.info("controlFileValid 83" + controlFileValid);
    }
    // Validate third part: YYYYMMDD.txt
    if (thirdPart) {
      //logger.info("inside third part" + thirdPart);
      var parts = String(thirdPart).split(".");
      //logger.info("parts1" + parts[1]);
      if (parts.length !== 2 || parts[1].toLowerCase() !== "txt") {
        isInvalidFile = true;
        controlFileValid = false;
        //logger.info("controlFileValid 97" + controlFileValid);
      } else {
        var datePart = parts[0]; // e.g. 20250708
        if (datePart.length !== 8 || !/^\d{8}$/.test(datePart)) {
          isInvalidFile = true;
          controlFileValid = false;
        }
        //logger.info("controlFileValid 103" + controlFileValid);
      }
    } else {
      isInvalidFile = true;
      failedDueToConvention = true;
      controlFileValid = false;
     // logger.info("controlFileValid 113" + controlFileValid);
    }
  }

  if (isInvalidFile) {
    errorsToAppend.push({
      code: errorCodes["EC001"]["code"],
      description: errorCodes["EC001"]["description"],
      fileName: originalFileName,
      status: "ERROR",
      deliveredDateTime: now,
    });
    controlFileValid = false;
    //logger.info("controlFileValid 128" + controlFileValid);
  } else {
    logger.info("controlFileValid 133" + controlFileValid);
    //channelMap.put("controlFileName", splittedFileName);
  }

 // logger.info("logger2" + content);
  if (typeof content !== "string") {
    content = String(content);
  }
  if (content.indexOf("\\n") !== -1) {
    content = content.replace(/\\r\\n/g, "\n").replace(/\\n/g, "\n");
  }
  var lines = content.split(/\r?\n/);
  //logger.info("lines" + lines.length);
  lines = lines.map(function (line) {
    return line.trim();
  });
  while (lines.length > 0 && lines[lines.length - 1] === "") {
    lines.pop();
  }
  //logger.info("lines2" + lines.length);
  if (lines.length != 0) {
    var header = controlFileHeader.toString().split("|");
    //logger.info("Parsed header: " + JSON.stringify(header));
    // Now do header check
    var actualHeader = lines[0].toString().split("|");
    logger.info("Expected header: " + JSON.stringify(header));
    logger.info("Actual header: " + JSON.stringify(actualHeader));
    var invalidDelimiterRegex = /[,\t; ]/;
    function isValidHeaderField(value) {
      return !invalidDelimiterRegex.test(value);
    }

    function arraysEqual(a1, a2) {
      if (a1.length !== a2.length) {
        logger.info(
          "Header length mismatch. Expected: " +
          a1.length +
          ", Actual: " +
          a2.length
        );
        return false;
      }
      if (a2.length <= 1) return false;
      for (var i = 0; i < a1.length; i++) {
        var val1 = a1[i].trim().toLowerCase();
        var val2 = a2[i].trim().toLowerCase();

        // Reject if any field contains a invalid delimeter— indicating mixed delimiters
        if (!isValidHeaderField(val1) || !isValidHeaderField(val2)) {
          logger.info("Invalid character in header field: " + a2[i]);
          return false;
        }

        if (val1 !== val2) {
          return false;
        }
      }
      return true;
    }

    if (!arraysEqual(header, actualHeader)) {
      errorsToAppend.push({
        code: errorCodes["EC003"]["code"],
        description: errorCodes["EC003"]["description"],
        fileName: originalFileName,
        status: "ERROR",
        deliveredDateTime: now,
      });
      controlFileValid = false;
    }

    // Now check data records
    if (lines.length < 2) {
      errorsToAppend.push({
        code: errorCodes["EC004"]["code"],
        description: errorCodes["EC004"]["description"],
        fileName: originalFileName,
        status: "ERROR",
        deliveredDateTime: now,
      });
      controlFileValid = false;
    }
    logger.info(lines.length);
    if (lines.length > 7) {
      logger.info(
        "Line ------------------------greater than 7 " + lines.length
      );
      errorsToAppend.push({
        code: errorCodes["EC013"]["code"],
        description: errorCodes["EC013"]["description"],
        fileName: originalFileName,
        status: "ERROR",
        deliveredDateTime: now,
      });
      controlFileValid = false;
      logger.info(
        "errorsToAppend---------" +
        JSON.stringify(errorsToAppend) +
        "------controlFileValid---------" +
        controlFileValid
      );
    }
    if (lines.length <= 6) {
      logger.info(
        "Line ------------------------greater than 5 " + lines.length
      );
      errorsToAppend.push({
        code: errorCodes["EC013"]["code"],
        description: errorCodes["EC013"]["description"],
        fileName: originalFileName,
        status: "ERROR",
        deliveredDateTime: now,
      });
      controlFileValid = false;
      logger.info(
        "errorsToAppend---------" +
        JSON.stringify(errorsToAppend) +
        "------controlFileValid---------" +
        controlFileValid
      );
    }

    try {
      dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        jdbdcDriver,
        jbdcUrl,
        dbName,
        dbPassword
      );

      var mco_id;
      var mco_name;

      var FileNameResult = dbConn.executeCachedQuery(
        "select mco_screening_id,status FROM screening_extracts.mco_screening_extracts where control_file_name = ? and is_active = '1'",
        [originalFileName]
      );

      //logger.info(FileNameResult.size());
      if (FileNameResult.next()) {
        var mco_screening_id = FileNameResult.getLong("mco_screening_id");

        var status = FileNameResult.getString("status");
        logger.info("status" + status + mco_screening_id);
        if (status == "ERROR" && mco_screening_id) {
          logger.info("inside status error case" + mco_screening_id);
          var updateResult = dbConn.executeCachedQuery(
            "update screening_extracts.mco_screening_extracts_details set is_active ='0',updated_on_utc = now() WHERE mco_screening_id = ? returning *",
            [mco_screening_id]
          );
          var updateResult = dbConn.executeCachedQuery(
            "update screening_extracts.mco_screening_extracts set is_active ='0',updated_on_utc = now() WHERE mco_screening_id = ? returning *",
            [mco_screening_id]
          );
        } else {
          logger.info("status is not error or invalid mco screening id");
          errorsToAppend.push({
            code: errorCodes["EC005"]["code"],
            description: errorCodes["EC005"]["description"],
            fileName: originalFileName,
            status: "ERROR",
          });
          controlFileValid = false;
        }
      }
    } catch (err) {
      // try {
      // 	dbConn = DatabaseConnectionFactory.createDatabaseConnection(
      // 		jdbdcDriver,
      // 		jbdcUrl,
      // 		dbName,
      // 		dbPassword
      // 	);
      // 	var error_type_id = errorTypeMap["POSTGRES_ERROR"]
      // 	var screening_id = channelMap.get("screeningId");
      // 	var mco_screening_details_id = channelMap.get("screeningDetailsId");
      // 	var fileResult = dbConn.executeCachedQuery(
      // 		"INSERT INTO screening_extracts.mco_screening_extracts_error_logs(mco_screening_id, error_json, created_on_utc, updates_on_utc, mco_screening_extracts_details_id, is_active, screening_error_type_id) VALUES (?, ?, NOW(),NOW(),?,'1',?)",
      // 		[screening_id,
      // 			JSON.stringify(err),
      // 			mco_screening_details_id,
      // 			error_type_id]

      // 	);

      // }
      // catch (err) {
      // 	throw err;
      // }
      logger.info(err);
      throw {
        errorType: "MIRTH INTERNAL ERROR",
        description: "Failed In reading control file",
        rawError: err,
        stackTrace: err.stack,
        msg: err.message,
        fileName: originalFileName,
      };
    }

    logger.info("controlFile status before execution" + controlFileValid);
  } else {
    try {
      dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        jdbdcDriver,
        jbdcUrl,
        dbName,
        dbPassword
      );

      var mco_id;
      var mco_name;

      var FileNameResult = dbConn.executeCachedQuery(
        "select mco_screening_id,status FROM screening_extracts.mco_screening_extracts where control_file_name = ? and is_active = '1'",
        [originalFileName]
      );

      logger.info(FileNameResult.size());
      if (FileNameResult.next()) {
        var mco_screening_id = FileNameResult.getLong("mco_screening_id");

        var status = FileNameResult.getString("status");
        logger.info("status" + status + mco_screening_id);
        if (status == "ERROR" && mco_screening_id) {
          logger.info("inside status error case" + mco_screening_id);
          var updateResult = dbConn.executeCachedQuery(
            "update screening_extracts.mco_screening_extracts_details set is_active ='0',updated_on_utc = now() WHERE mco_screening_id = ? returning *",
            [mco_screening_id]
          );
          var updateResult = dbConn.executeCachedQuery(
            "update screening_extracts.mco_screening_extracts set is_active ='0',updated_on_utc = now() WHERE mco_screening_id = ? returning *",
            [mco_screening_id]
          );
        } else {
          logger.info("status is not error or invalid mco screening id");
          errorsToAppend.push({
            code: errorCodes["EC005"]["code"],
            description: errorCodes["EC005"]["description"],
            fileName: originalFileName,
            status: "ERROR",
          });
          controlFileValid = false;
        }
      }
    } catch (err) {
      logger.info(err);
      throw {
        errorType: "MIRTH INTERNAL ERROR",
        description: "Failed In reading control file",
        rawError: err,
        stackTrace: err.stack,
        msg: err.message,
        fileName: originalFileName,
      };
    }
    errorsToAppend.push({
      code: errorCodes["EC002"]["code"],
      description: errorCodes["EC002"]["description"],
      fileName: originalFileName,
      status: "ERROR",
      deliveredDateTime: now,
    });
    controlFileValid = false;
  }

  if (controlFileValid) {
    var dataRecords = lines.slice(1); // exclude header
    var msgObj = [];
    channelMap.put("errorCodes", errorsToAppend);

    for (var i = 0; i < dataRecords.length; i++) {
      var fields = dataRecords[i].split("|").map(function (val) {
        return val.trim();
      });

      var recordObj = {};
      for (var j = 0; j < header.length; j++) {
        recordObj[header[j]] = fields[j] || "";
      }
      //logger.info(recordObj);

      msgObj.push(recordObj);
    }

    var duplicates = [];
    for (var i = 0; i < msgObj.length; i++) {
      var rowNumber = i + 1;
      var row = msgObj[i];
      var errorDescription = [];
      var temp = {
        fileName: "",
        rowCount: "",
        createdTime: "",
        skipFile: false,
        size: "",
      };
      //            var controlFileDetails = {
      //                "mcoCode": "",
      //                "fileName": "",
      //                "rowCount": "",
      //                "extractRunTime": "",
      //                "previousRunTime": ""
      //            }
      // var mco =   globalChannelMap.get("mcoCode");
      var validMco = true;
      if (msgObj[i]["MCO_CODE"].trim() === "") {
        errorsToAppend.push({
          code: errorCodes["EC006"]["code"],
          description: errorCodes["EC006"]["description"],
          fileName: msgObj[i]["FILE_NAME"],
          status: "ERROR",
        });
      }
      // else if(msgObj[i]["MCO_CODE"] == mco ){
      //      errorsToAppend.push({

      //         code: errorCodes["EC016"]["code"],
      //         description: errorCodes["EC016"]["description"],
      //         fileName: msgObj[i]["FILE_NAME"],
      //         status: "ERROR"
      //     });
      //     validMCO=false
      // }
      else {
        //                controlFileDetails["mcoCode"] = msgObj[i]["MCO_CODE"]
      }

      if (msgObj[i]["FILE_NAME"].trim() === "") {
        errorsToAppend.push({
          code: errorCodes["EC007"]["code"],
          description: errorCodes["EC007"]["description"],
          fileName: msgObj[i]["FILE_NAME"],
          status: "ERROR",
        });
      } else {
        temp["fileName"] = msgObj[i]["FILE_NAME"];

        // fileNames.push(msgObj[i]["FILE_NAME"])
        //                controlFileDetails["fileName"] = msgObj[i]["FILE_NAME"]
      }

      // if (msgObj[i]["TARGET_DESTINATION_NAME"].trim() === '') {
      //     errorsToAppend.push({

      //         code: errorCodes["EC008"]["code"],
      //         description: errorCodes["EC008"]["description"],
      //         fileName: msgObj[i]["FILE_NAME"],
      //         status: "ERROR"
      //     });
      // }
      // else {
      //     controlFileDetails["targetDestination"] = msgObj[i]["TARGET_DESTINATION_NAME"]
      // }
      var rowCountStr = msgObj[i]["ROW_COUNT"];
      var converted = Number(rowCountStr);
      if (msgObj[i]["ROW_COUNT"].trim() === "") {
        errorsToAppend.push({
          code: errorCodes["EC009"]["code"],
          description: errorCodes["EC009"]["description"],
          fileName: msgObj[i]["FILE_NAME"],
          status: "ERROR",
        });
      } else if (isNaN(converted) || converted < 0) {
        errorsToAppend.push({
          code: errorCodes["EC015"]["code"],
          description: errorCodes["EC015"]["description"],
          fileName: msgObj[i]["FILE_NAME"],
          status: "ERROR",
        });
      } else if (msgObj[i]["ROW_COUNT"] === "0") {
        temp["skipFile"] = true;
        temp["rowCount"] = msgObj[i]["ROW_COUNT"];
        //                controlFileDetails["mcoCode"] = msgObj[i]["ROW_COUNT"]
      } else {
        temp["rowCount"] = msgObj[i]["ROW_COUNT"];
        //                controlFileDetails["mcoCode"] = msgObj[i]["ROW_COUNT"]
      }
      // if (msgObj[i]["EXTRACT_RUN_TIME"].trim() === "") {
      //   errorsToAppend.push({
      //     code: errorCodes["EC010"]["code"],
      //     description: errorCodes["EC010"]["description"],
      //     fileName: msgObj[i]["FILE_NAME"],
      //     status: "ERROR",
      //     deliveredDateTime: msgObj[i]["EXTRACT_RUN_TIME"],
      //   });
      // } else {
      //   temp["createdTime"] = msgObj[i]["EXTRACT_RUN_TIME"];
        //                controlFileDetails["extractRunTime"] = msgObj[i]["EXTRACT_RUN_TIME"]
      //}
      //      if (msgObj[i]["PREVIOUS_EXTRACT_RUN_TIME"].trim() === "") {
      //        errorsToAppend.push({
      //          code: errorCodes["EC011"]["code"],
      //          description: errorCodes["EC011"]["description"],
      //          fileName: msgObj[i]["FILE_NAME"],
      //          status: "ERROR",
      //          deliveredDateTime: msgObj[i]["EXTRACT_RUN_TIME"],
      //        });
      //      } else {
      //        //                controlFileDetails["previousRunTime"] = msgObj[i]["PREVIOUS_EXTRACT_RUN_TIME"]
      //      }
      fileInformation.push(temp);
      //            controlFileContent.push(controlFileDetails);
      var fname = msgObj[i]["FILE_NAME"].trim();
      var splittedFname = fname.split("_");
      logger.info("before lower case call" + splittedFname);
      if (splittedFname && splittedFname.length != 3) {
        errorsToAppend.push({
          code: errorCodes["EC016"]["code"],
          description: errorCodes["EC016"]["description"],
          fileName: originalFileName,
          status: "ERROR",
          deliveredDateTime: now,
        });
      } else {
        var secondPartFname = splittedFname[1].toLowerCase();

        for (var j = 0; j < filePart.length; j++) {
          var type = filePart[j];
          //logger.info(secondPartFname);
          if (secondPartFname === type.toLowerCase()) {
            logger.info("inside if for type  check" + type);
            filePartJSON[type] = filePartJSON[type] + 1;
          }
          if (filePartJSON[type] > 1) {
            errorsToAppend.push({
              code: errorCodes["EC014"]["code"],
              description: errorCodes["EC014"]["description"],
              fileName: originalFileName,
              status: "ERROR",
              deliveredDateTime: now,
            });
          }
        }
        //logger.info(JSON.stringify(filePartJSON));
      }
    }
    // for (var key in filePartJSON) {
    //     logger.info("inside duplicate check"+key+filePartJSON[key])
    //     if (filePartJSON[key] > 1) {
    //         duplicates.push(key);
    //     }
    // }
    // logger.info(duplicates.length)
    // if (duplicates.length > 0) {

    // }
    channelMap.put("fileInformation", fileInformation);
    logger.info("before middle");
    if (errorsToAppend.length == 0) {
      logger.info("inside valid control file logic");
      try {
        fileInformation.push({
          fileName: String(originalFileName),
          rowCount: msgObj.length,
          createdTime: "",
          skipFile: false,
        });

        channelMap.put("fileInformation", fileInformation);

        var JSch = Packages.com.jcraft.jsch.JSch;
        var session = null,
          channel = null;

        var JSch = Packages.com.jcraft.jsch.JSch;
        var session = null,
          channel = null;

        try {
          var sftpClient = new JSch();
          sftpClient.addIdentity(privateKey);
          session = sftpClient.getSession(username, ip, port);
          session.setPassword(password);
          logger.info("before session connect")
          var config = new java.util.Properties();
          config.put("StrictHostKeyChecking", "no");
          session.setConfig(config);
          session.connect();

          channel = session.openChannel("sftp");
          channel.connect();
          sftp = channel;// ChannelSftp object
logger.info("after session connect")
          var mcoCode = channelMap.get("mcoCode");
          var sourceBase = screeningLocation[mcoCode]["inbound"]
            ? screeningLocation[mcoCode]["inbound"]
            : generalInbound;
          var destBase1 = screeningLocation[mcoCode]["nyecProcessed"]
            ? screeningLocation[mcoCode]["nyecProcessed"]
            : generalProcessed; // move destination
          var destBase2 = screeningLocation[mcoCode]["rawFolder"]; // copy destination

          // List files from source folder
          var availableFilesMap = new java.util.HashMap();
          var sizeZeroMap = new java.util.HashMap();
          var fileSizeMap = new java.util.HashMap();
          logger.info("sourceBase"+sourceBase)
          var list = sftp.ls(sourceBase);
          logger.info("after sftp ls")
          var it = list.iterator();
          while (it.hasNext()) {
            var entry = it.next();
            if (!entry.getAttrs().isDir()) {
              var actualName = entry.getFilename();
              var size = entry.getAttrs().getSize();
              logger.info("Remote file: [" + actualName + "] | Size: " + size + " bytes");
              fileSizeMap.put(actualName.trim(), size);

              if (size <= 0) {
                // save non-empty files
                sizeZeroMap.put(actualName.trim(), true);
                logger.warn("Skipping empty file: " + actualName);
              } else {
                availableFilesMap.put(actualName.trim(), actualName);
              }
            }
          }
          //logger.info("while completed")

          // Process input files
          for (var i = 0; i < fileInformation.length; i++) {
            var fi = fileInformation[i];
            if (fi.skipFile) continue;

            var requestedName = fi.fileName.trim();
            //logger.info(requestedName);
            var actualFileName = availableFilesMap.get(requestedName);
            var sizeZeroFile = sizeZeroMap.get(requestedName);
            //logger.info("size zero file" + sizeZeroFile);

            if (sizeZeroFile) {
              logger.info("Handling zero-byte file: " + requestedName);

              // Construct remote path for MOVE
              var dstMove = destBase1 + "/" + requestedName;

              // Create empty file remotely
              var out = sftp.put(dstMove, sftp.OVERWRITE);
              out.close();
              logger.info("Created empty remote file at: " + dstMove);

              // Delete original remote file
              var src = sourceBase + "/" + requestedName;
              sftp.rm(src);
              logger.info("Deleted original zero-byte remote file: " + src);
              logger.info("inside zero file case");
              errorsToAppend.push({
                code: errorCodes["EC002"]["code"],
                description: errorCodes["EC002"]["description"],
                fileName: requestedName,
                status: "ERROR",
                deliveredDateTime: now,
              });
              validationStatus = false;
              continue;
            }

            if (actualFileName == null) {
              errorsToAppend.push({
                description: errorCodes["EC012"]["description"],
                fileName: requestedName,
                status: "ERROR",
                deliveredDateTime: now,
              });
              validationStatus = false;
              logger.warn("Skipping missing or empty file: " + requestedName);
              continue;
            }

            var fileSize = fileSizeMap.get(requestedName).toString();
